import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@Controller
public class RSocketController {

    @MessageMapping("stock.stream")
    public Flux<StockTick> streamStockPrices(String ticker) {
        return Flux.interval(Duration.ofSeconds(1))
                ános -> new StockTick(ticker, Math.random() * 100);
    }

    @MessageMapping("user.profile")
    public Mono<UserProfile> getProfile(Long userId) {
        return Mono.just(new UserProfile(userId, "Enterprise Architect"));
    }
}
